package tracing

import (
	"context"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
	"go.flipt.io/flipt/internal/config"
	"go.opentelemetry.io/otel/attribute"
	tracesdk "go.opentelemetry.io/otel/sdk/trace"
)

func TestNewResource(t *testing.T) {
	t.Setenv("OTEL_SERVICE_NAME", "")
	t.Setenv("OTEL_RESOURCE_ATTRIBUTES", "")

	res, err := newResource(context.Background(), "1.2.3")
	require.NoError(t, err)
	requireResourceAttribute(t, res.Attributes(), "service.name", "flipt")
	requireResourceAttribute(t, res.Attributes(), "service.version", "1.2.3")

	t.Setenv("OTEL_SERVICE_NAME", "environment-service")
	t.Setenv("OTEL_RESOURCE_ATTRIBUTES", "deployment.environment=testing,team=platform")

	res, err = newResource(context.Background(), "4.5.6")
	require.NoError(t, err)
	requireResourceAttribute(t, res.Attributes(), "service.name", "environment-service")
	requireResourceAttribute(t, res.Attributes(), "service.version", "4.5.6")
	requireResourceAttribute(t, res.Attributes(), "deployment.environment", "testing")
	requireResourceAttribute(t, res.Attributes(), "team", "platform")
}

func requireResourceAttribute(t *testing.T, attrs []attribute.KeyValue, key, want string) {
	t.Helper()
	for _, attr := range attrs {
		if string(attr.Key) == key {
			require.Equal(t, want, attr.Value.AsString(), "resource attribute %s", key)
			return
		}
	}
	t.Fatalf("missing resource attribute %s", key)
}

func TestNewProviderAlwaysSamples(t *testing.T) {
	t.Setenv("OTEL_TRACES_SAMPLER", "always_off")

	provider, err := NewProvider(context.Background(), "1.2.3")
	require.NoError(t, err)
	t.Cleanup(func() { require.NoError(t, provider.Shutdown(context.Background())) })

	_, span := provider.Tracer("test").Start(context.Background(), "operation")
	require.True(t, span.IsRecording())
	span.End()
}

func TestGetExporter(t *testing.T) {
	tests := []struct {
		name string
		cfg  config.TracingConfig
	}{
		{
			name: "Jaeger",
			cfg: config.TracingConfig{
				Exporter: config.TracingJaeger,
				Jaeger:   config.JaegerTracingConfig{Host: "localhost", Port: 6831},
			},
		},
		{
			name: "Zipkin",
			cfg: config.TracingConfig{
				Exporter: config.TracingZipkin,
				Zipkin:   config.ZipkinTracingConfig{Endpoint: "http://localhost:9411/api/v2/spans"},
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			exporter, shutdown, err := GetExporter(context.Background(), &tt.cfg)
			require.NoError(t, err)
			require.NotNil(t, exporter)
			require.NotNil(t, shutdown)
			require.NoError(t, shutdown(context.Background()))
		})
	}
}

func TestGetExporterOTLPEndpoints(t *testing.T) {
	for _, endpoint := range []string{
		"http://localhost:4318",
		"https://localhost:4318",
		"grpc://localhost:4317",
		"localhost:4317",
	} {
		t.Run(endpoint, func(t *testing.T) {
			cfg := config.TracingConfig{
				Exporter: config.TracingOTLP,
				OTLP: config.OTLPTracingConfig{
					Endpoint: endpoint,
					Headers:  map[string]string{"api-key": "test-key"},
				},
			}
			exporter, shutdown, err := GetExporter(context.Background(), &cfg)
			require.NoError(t, err)
			require.NotNil(t, exporter)
			require.NotNil(t, shutdown)
			require.NoError(t, shutdown(context.Background()))
		})
	}
}

func TestGetExporterInvalidEndpointsAndUnsupportedExporter(t *testing.T) {
	for _, endpoint := range []string{"http://%zz", "grpc://"} {
		t.Run(endpoint, func(t *testing.T) {
			cfg := config.TracingConfig{
				Exporter: config.TracingOTLP,
				OTLP:     config.OTLPTracingConfig{Endpoint: endpoint},
			}
			_, _, err := GetExporter(context.Background(), &cfg)
			require.Error(t, err)
			require.Contains(t, err.Error(), "otlp endpoint")
		})
	}

	cfg := config.TracingConfig{Exporter: config.TracingExporter(99)}
	_, _, err := GetExporter(context.Background(), &cfg)
	require.Error(t, err)
	require.True(t, strings.HasPrefix(err.Error(), "unsupported tracing exporter:"), err.Error())

	// A failed call must not prevent a later valid configuration from working.
	cfg = config.TracingConfig{
		Exporter: config.TracingZipkin,
		Zipkin:   config.ZipkinTracingConfig{Endpoint: "http://localhost:9411/api/v2/spans"},
	}
	for range 2 {
		exporter, shutdown, err := GetExporter(context.Background(), &cfg)
		require.NoError(t, err)
		require.NotNil(t, exporter)
		require.NoError(t, shutdown(context.Background()))
	}
}

func TestGetExporterOTLPHTTPHeaders(t *testing.T) {
	received := make(chan http.Header, 1)
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/v1/traces" {
			http.Error(w, fmt.Sprintf("unexpected path %s", r.URL.Path), http.StatusNotFound)
			return
		}
		select {
		case received <- r.Header.Clone():
		default:
		}
		w.WriteHeader(http.StatusOK)
	}))
	t.Cleanup(server.Close)

	cfg := config.TracingConfig{
		Exporter: config.TracingOTLP,
		OTLP: config.OTLPTracingConfig{
			Endpoint: server.URL,
			Headers:  map[string]string{"api-key": "test-key"},
		},
	}
	exporter, shutdown, err := GetExporter(context.Background(), &cfg)
	require.NoError(t, err)
	t.Cleanup(func() { require.NoError(t, shutdown(context.Background())) })

	provider := tracesdk.NewTracerProvider(tracesdk.WithSyncer(exporter))
	t.Cleanup(func() { require.NoError(t, provider.Shutdown(context.Background())) })
	_, span := provider.Tracer("test").Start(context.Background(), "request")
	span.End()

	select {
	case headers := <-received:
		require.Equal(t, "test-key", headers.Get("api-key"))
	case <-time.After(3 * time.Second):
		t.Fatal("OTLP HTTP exporter did not send a trace")
	}
}

